export const AmapaInteractiveMap: React.FC<AmapaInteractiveMapProps> = ({
  selectedMunicipality,
  onMunicipalitySelect,
  highlightColor = 'hsl(45, 100%, 50%)', // Bright Yellow for selected
  hoverColor = 'hsl(185, 70%, 80%)',      // Light Blue/Cyan for hover
  strokeColor = 'hsl(0 0% 100%)',        // White for strokes
  strokeWidth = 2, // Adjusted stroke width
  className,
}) => {
  const [hoveredMunicipality, setHoveredMunicipality] = useState<string | null>(null);

  const getFillColor = (municipalityName: string) => {
    if (municipalityName === selectedMunicipality) {
      return highlightColor;
    }
    if (municipalityName === hoveredMunicipality) {
      return hoverColor;
    }
    return municipalityDefaultColors[municipalityName] || 'hsl(170, 50%, 80%)'; // Fallback light teal
  };

  const commonPathProps = (municipalityName: string) => ({
    style: {
      fill: getFillColor(municipalityName),
      stroke: strokeColor,
      strokeWidth: strokeWidth,
      fillOpacity: 1,
      strokeOpacity: 1,
      transition: 'fill 0.15s ease-in-out',
    },
    onClick: () => onMunicipalitySelect(municipalityName === selectedMunicipality ? null : municipalityName),
    onMouseEnter: () => setHoveredMunicipality(municipalityName),
    onMouseLeave: () => setHoveredMunicipality(null),
    className: "cursor-pointer",
  });

  const allMunicipalities = [
    "Amapá", "Calçoene", "Cutias", "Ferreira Gomes", "Itaubal",
    "Laranjal do Jari", "Macapá", "Mazagão", "Oiapoque",
    "Pedra Branca do Amaparí", "Porto Grande", "Pracuúba", "Santana",
    "Serra do Navio", "Tartarugalzinho", "Vitória do Jari"
  ];
  
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      id="amapa-interactive-svg"
      viewBox="0 0 2048 2314.0649"
      className={cn("w-full h-auto max-w-md mx-auto", className)}
      aria-label="Mapa interativo do Estado do Amapá"
    >
      <defs></defs>
      <g id="Camada_x0020_1">
        {allMunicipalities.map((name) => {
          const pathData = (existingPaths as any)[name];
          if (pathData) {
            return <path key={name} id={name} d={pathData} {...commonPathProps(name)} />;
          }
          // Adding HTML comments within JSX for missing paths
          return (
            <React.Fragment key={name}>
              {/* TODO: Add <path id="{name}" d="..." /> here */}
            </React.Fragment>
          );
        })}
      </g>
    </svg>
  );
};

export default AmapaInteractiveMap;

    